        backup_NETSNMP_DS_LIB_OUTPUT_PRECISION =
            strdup(netsnmp_ds_get_string(NETSNMP_DS_LIBRARY_ID, NETSNMP_DS_LIB_OUTPUT_PRECISION));
    }

